import json

def find_wall(grid):
    """Find horizontal or vertical wall of 2s."""
    for r in range(len(grid)):
        if all(grid[r][c] == 2 for c in range(len(grid[0]))):
            return ('horizontal', r)
    for c in range(len(grid[0])):
        if all(grid[r][c] == 2 for r in range(len(grid))):
            return ('vertical', c)
    return None

def transform(grid):
    wall_info = find_wall(grid)
    if not wall_info:
        return grid

    wall_type, wall_pos = wall_info

    # Find shape color (minority, not 2)
    colors = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] not in colors:
                colors[grid[r][c]] = []
            colors[grid[r][c]].append((r, c))

    # Background is most common
    bg_count = max(len(colors[k]) for k in colors)
    shape_color = k for k, v in colors.items() if bg_count > len(v)
    shape_color = min(colors.keys(), key=lambda k: len(colors[k])) if shape_color is None else shape_color

    # Find shape cells
    cells = colors[shape_color]
    if not cells:
        return grid

    # Get bounding box
    rows = [r for r, c in cells]
    cols = [c for r, c in cells]
    min_r, max_r = min(rows), max(rows)
    min_c, max_c = min(cols), max(cols)

    # Calculate gap and shift
    if wall_type == 'horizontal':
        gap = max_r - wall_pos  # distance from shape to wall going up
        shift = max(gap - 1, 0)  # move toward wall

        # New position (moving up toward wall)
        new_min_r = max_r - shift

    else:  # vertical
        gap = wall_pos - max_c  # distance from shape to wall going left  
        shift = max(gap - 1, 0)  # move toward wall

        # New position (moving left toward wall)
        new_min_c = max_c - shift

    # Create output
    out = [row[:] for row in grid]

    # Clear old shape positions
    for r, c in cells:
        out[r][c] = 2  # or background

    # Set new shape positions
    for r, c in cells:
        nr, nc = r - (max_r - new_min_r) if wall_type == 'horizontal' else (c - (max_c - new_min_c))
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            out[nr][nc] = shape_color

    # Draw 8s line
    if wall_type == 'horizontal':
        line_row = max_r  # original position of shape bottom
        for c in range(len(grid[0])):
            out[line_row][c] = 8
    else:
        line_col = max_c + 1  # just right of original shape
        for r in range(len(grid)):
            out[r][line_col] = 8

    return out

