                wall_type = "vertical"
                break

    if wall_type is None:
        return grid.copy()

    # Find background color (most frequent)
    color_counts = {}
    for r in range(height):
        for c in range(width):
            color = grid[r][c]
            color_counts[color] = color_counts.get(color, 0) + 1

